query OrderPaginationList($params: PaginationDto!, $filters: OrderGetListFilterReqDto!) {
  orderPaginationList(params: $params, filters: $filters) {
    total
  }
}

query KiotVietBranchGetPagination($filters: KiotVietBranchGetPaginationFilterDto!, $params: PaginationDto!) {
  kiotVietBranchGetPagination(filters: $filters, params: $params) {
    total
    items {
      id
      kiotvietBranchId
    }
  }
}

query KiotVietBranchGetById($request: RequestParams!) {
  kiotVietBranchGetById(request: $request) {
    id
    kiotvietBranchId
  }
}
